package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;

/** Actual original registration/day/P1/P2/native leaves. Already-applied model genesis is explicitly fictional. */
@EnabledIfEnvironmentVariable(named="B45_MYSQL",matches="true")
class NewsDayReportEntityLeavesMySqlTest extends NewsDayReportEntityLeavesTest {
    @Override GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreMySqlTest();}
    NewsDayReportComponentMySqlTest nativeDay;
    void completed()throws Exception{nativeDay=new NewsDayReportComponentMySqlTest();nativeDay.nativeSetup(false);var pipeline=nativeDay.pipeline;pipeline.projectFictionalAppliedMember();String owner=pipeline.child();pipeline.preparation.prepareValue(owner,pipeline.day.run(),pipeline.day.original.ref,0);var ref=pipeline.f.reference(owner);pipeline.f.completeP2(ref);pipeline.day.graph.finalization().finish(ref);pipeline.day.graph.finalObserver().capture(ref);nativeDay.nativeLeaves(ref);}
    @Test void ActualIncludedP1IsQualifiedBeforeP2HandoffWithoutInventingAnEntityBody()throws Exception{nativeDay=new NewsDayReportComponentMySqlTest();nativeDay.nativeSetup(false);nativeDay.pipeline.day.barriers.close(nativeDay.pipeline.day.day);var value=nativeDay.nativeCapture();assertEquals("value_handoff_unproven",value.missing().getFirst().reason());assertTrue(value.entityLeaves().isEmpty());assertEquals(1,value.includedDedupPlans().size());var original=value.includedDedupPlans().getFirst();assertEquals(nativeDay.pipeline.day.original.ref,original.reference());assertEquals(value.day(),original.day());assertEquals(nativeDay.pipeline.day.run(),original.runId());assertFalse(original.toString().contains(original.sourceId()));assertSame(value,nativeDay.nativeRr(()->nativeDay.nativeService.verifyObserved(value)));assertThrows(UnsupportedOperationException.class,()->value.includedDedupPlans().clear());}
    @Test void ActualRegistrationAndOriginalP1OwnerDamageCannotRetainSourceQualification()throws Exception{completed();var value=nativeDay.nativeCapture();assertEquals(1,value.includedDedupPlans().size());nativeDay.pipeline.f.db.jdbc.update("UPDATE jobs SET generation=2 WHERE id=?",value.includedDedupPlans().getFirst().reference().ownerId());assertThrows(RuntimeException.class,()->nativeDay.nativeRr(()->nativeDay.nativeService.verifyObserved(value)));assertThrows(RuntimeException.class,nativeDay::nativeCapture);}
    @Test void ActualRegisteredWholeDayContainsEveryOriginalEntityLeafAndFullReferences()throws Exception{completed();var value=nativeDay.nativeCapture();assertFalse(value.entityLeaves().isEmpty());assertTrue(value.missing().isEmpty());var roots=new HashSet<String>();for(var leaf:value.entityLeaves()){assertEquals(value.day(),leaf.day());assertNotNull(leaf.entityId());assertEquals(CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(leaf.bodyJson())),leaf.bodyHash());assertEquals("article_revision",CanonicalJson.parse(leaf.referenceJson()).get("kind").asText());assertFalse(leaf.availableAt().isAfter(value.cutoff()));roots.add(leaf.rootId());}assertTrue(value.dependencies().stream().map(GenerationFlowService.Dependency::id).toList().containsAll(roots));assertTrue(value.originalByteSize()>value.entityLeaves().stream().mapToLong(l->l.bodyJson().getBytes(java.nio.charset.StandardCharsets.UTF_8).length).sum());assertSame(value,nativeDay.nativeRr(()->nativeDay.nativeService.verifyObserved(value)));assertThrows(UnsupportedOperationException.class,()->value.entityLeaves().clear());}
    @Test void WholeDayRereadRejectsChangedNativeLeafValidityAndFreshFactsCarryTheChange()throws Exception{completed();var old=nativeDay.nativeCapture();var leaf=old.entityLeaves().getFirst();nativeDay.pipeline.f.db.jdbc.update("UPDATE article_revisions SET effective_valid=0,validity_revision=validity_revision+1 WHERE id=?",CanonicalJson.parse(leaf.referenceJson()).get("id").asText());assertThrows(RuntimeException.class,()->nativeDay.nativeRr(()->nativeDay.nativeService.verifyObserved(old)));var changed=nativeDay.nativeCapture().entityLeaves().stream().filter(l->l.itemId().equals(leaf.itemId())).findFirst().orElseThrow();assertFalse(changed.effectiveValid());assertEquals(leaf.bodyJson(),changed.bodyJson());assertEquals(leaf.validityRevision()+1,changed.validityRevision());}
    @Test void MissingNativeRegistrationOrImmutableLeafCannotRetainBodyAuthority()throws Exception{completed();var old=nativeDay.nativeCapture();nativeDay.pipeline.f.db.jdbc.update("UPDATE source_run_items SET article_revision_id=NULL");assertThrows(RuntimeException.class,()->nativeDay.nativeRr(()->nativeDay.nativeService.verifyObserved(old)));var missing=nativeDay.nativeCapture();assertTrue(missing.entityLeaves().isEmpty());assertTrue(missing.missing().stream().anyMatch(m->m.reason().equals("source_leaf_unproven")));nativeDay.pipeline.f.db.jdbc.update("DELETE FROM request_receipts WHERE actor_id='source-day-register'");assertThrows(RuntimeException.class,nativeDay::nativeCapture);}
}
